_CARRY_REF = True


def _tup(x: Any) -> Any:
    """A carried key back from JSON: every list a tuple again, so it meets the in-game key."""
    return tuple(_tup(v) for v in x) if isinstance(x, list | tuple) else x


def _kind_of(out_t: str) -> str:
    """A stream's kind, from its output type."""
    return ("predictor" if out_t == "val"
            else "objective" if out_t == OBJ_TYPE else f"typed:{out_t}")


def _floor_champion(by_kind: dict, kind: str, best, share: bool):
    """D2: the champion a stream's floor test reads. ON: its own kind's (the reviewer 06:19 CDT).
    OFF: the shared best, as before."""
    return by_kind.get(kind) if share else best


def _next_stream(live: list, spent: dict, share: bool, key: str | None = None,
                 seed: str | None = None) -> int:
    """D2: the stream that takes the next candidate. OFF: the first live stream, which is the old
    sequence (each stream to exhaustion before the next). ON: the least rank spent this round,
    ties to the lower stream id; under TETHER_A1_STREAM (site 4) an exact tie goes to the draw,
    never to the list order. No share, weight or quota."""
    if share and key is not None:
        return min(live, key=lambda s: (spent[s], FR.draw_key(key, s, seed)))
    return min(live, key=lambda s: (spent[s], s)) if share else live[0]


def _merge_by_depth(lib_chains: list, closure, evidence: dict, key: str, seed: str | None = None):
    """A1 site 6 (the reviewer 2026-10-15 09:05 U3, 14:23): the library's chains enter the closure's
    own walk order (shortest first) at their own depth, never all ahead of it. Within a depth,
    evidence (the entries that offered the chain) orders a library chain ahead of the closure's,
    which carry none; library chains tied on depth and evidence go by the recorded draw. Nothing is
    enumerated twice: the closure is walked once, as before."""
    pend = sorted(lib_chains, key=lambda c: (len(c.atoms), -evidence.get(c.name, 0),
                                             FR.draw_key(key, c.name, seed)))
    i = 0
    for c in closure:
        cap.head()
        while i < len(pend) and len(pend[i].atoms) <= len(c.atoms):
            cap.head()
            yield pend[i]
            i += 1
        yield c
    yield from pend[i:]


def _test_outcome(before: Any, after: Any, target: Any, ordered: bool,
                  aim: str | None = None) -> str:
    """7j: what the ground showed against what the term predicted. Closer and farther need an
    ORDERED value (the slot's own type, ORDERED_TYPES); a categorical value is reached or not
    (J-a, the reviewer 2026-10-15 20:27).
    R-C (`aim` given only under TETHER_ROUTE_REFUSE; the reviewer 2026-10-24 09:30, 09:37): the gap
    is SIGNED (Fig 12 :120, Fig 5 :59). A GENERAL intent states a direction only, so any move that
    way is reached, whatever its size, and only the wrong way is farther. A SPECIFIC intent states
    its target, so a press past it -- the gap changing sign -- is "overshot": information, not
    failure."""
    if after is None:
        return "slot gone"
    if after == target:
        return "reached"
    if after == before:
        return "no change"
    # J-c (the reviewer 2026-10-15 20:41): a value that is not a number (None, a tuple, a
    # string) cannot be closer or farther, so it is graded as categorical
    num = all(isinstance(v, (int, float)) and not isinstance(v, bool)
              for v in (before, after, target))
    if not ordered or not num:
        return "not reached"
    if aim == "general":
        return "reached" if (after - before) * (target - before) > 0 else "farther"
    if aim == "specific" and (before - target) * (after - target) < 0:
        return "overshot"
    return "closer" if abs(after - target) < abs(before - target) else "farther"


def _draw_ties(items, num, key: str, seed) -> list:
    """(name, value) items ordered by num(item); a run equal on num is ordered by the recorded draw
    of its names (A1: never a name). Only a tied run is hashed. Sorting by (num, draw) exactly."""
    out = sorted(items, key=lambda kv: (num(kv), kv[0]))
    i = 0
    while i < len(out):
        cap.head()
        j, at = i + 1, num(out[i])
        while j < len(out) and num(out[j]) == at:
            cap.head()
            j += 1
        if j - i > 1:
            out[i:j] = sorted(out[i:j], key=lambda kv: (FR.draw_key(key, kv[0], seed), kv[0]))
        i = j
    return out


def _lookup_order(names: list, comp: dict, dk: str, evidence=None, seed=None) -> list:
    """A1 sites 7-8 (the reviewer 2026-10-15 14:23, 14:27): the shape's order over operand slots.
    comp[s] = (contact, derived, library evidence, distinct values over the failing frames): the
    residual GATE (in contact with the open slot's owner, 0 first), the ACTIONS walk (a derived
    slot is one more composition step), BITS inside it (more evidence first), the residual
    MAGNITUDE (more distinct values first), then the recorded draw. `evidence` replaces the
    library count (site 7: this chain's offers). LEAST-KNOWN is comp[s][4] when present (7h's
    tried count this level, fewer first), before the draw. 7m puts ANALOGY before it (a kind
    pair seen before, first): the extra fields are read in order, so OFF keeps today's key."""
    def ev(s):
        return comp[s][2] if evidence is None else evidence(s)
    return sorted(names, key=lambda s: (comp[s][0], comp[s][1], -ev(s), -comp[s][3],
                                        *comp[s][4:], FR.draw_key(dk, s, seed)))


class _PricedDomain(frozenset):
    """A1 site 9 (U2, the reviewer 2026-10-15 09:05, 14:23): the values an objective searches FIRST
    (shown before this frame, and each operand +-1), carrying what prices the rest of the alphabet:
    its size, the shown counts, the draw key and the agent's row writer. Nothing is removed."""


def _priced_hit(evaluate, current: int, ordered: bool, dom: _PricedDomain):
    """The satisfying value an objective aims at, read in two currencies held apart (Fig 12):
    DISTANCE from current (actions) and NOVELTY (bits: 0 if shown, else log2 of the count of
    unseen values). Only two values can be on the frontier: the nearest satisfying shown value,
    and the nearest satisfying unseen one NEARER than it (a farther unseen one is dominated), so
    the unseen walk stops at the shown answer's distance. Comparable-only: every distance is
    equal, so a shown value dominates and the unseen are searched only when none is shown.
    Values at one distance are tied, and the recorded draw decides, never the lower value (F1,
    the reviewer 2026-10-15 14:42; TIES: never a position)."""
    def dk(v):
        return FR.draw_key(dom.key, v, getattr(dom, "seed", None))
    walk = sorted(dom, key=(lambda v: (abs(v - current), dk(v))) if ordered else dk)
    shown = next((v for v in walk if v != current and evaluate(v)), None)
    if shown is not None and not ordered:
        return shown
    limit = (abs(shown - current) if shown is not None else dom.alpha) if ordered else None
    brk = getattr(evaluate, "breaks", None) if _INTERVAL_BOUND else None
    cuts = brk() if brk is not None else None
    if cuts is not None and ordered and limit - 1 <= len(cuts) + 1:
        cuts = None     # the rings evaluate no more values than the pieces would: walked
    if cuts is not None:
        INTERVAL_N["bound"] += 1
        unseen = _bound_unseen(evaluate, current, ordered, dom, cuts, limit, dk)
    if cuts is None or _INTERVAL_BOUND_CHECK:
        walked = _walk_unseen(evaluate, current, ordered, dom, limit, dk)
        if cuts is None:
            INTERVAL_N["walk"] += 1
        elif walked == unseen:
            INTERVAL_N["agree"] += 1
        else:
            INTERVAL_N["disagree"] += 1
            if len(INTERVAL_DISAGREE) < 20:
                INTERVAL_DISAGREE.append({"current": current, "ordered": ordered,
                                          "alpha": dom.alpha, "bound": unseen, "walk": walked})
        unseen = walked
    if unseen is PURSE_CUT:
        # C2 P1: the purse stopped the walk -- unreached at this budget, never "no value": the
        # shown answer stands if there is one, else the objective could not be read (Fig 9 :60)
        dom.purse_note(shown)
        return shown if shown is not None else NOT_RESOLVED
    if unseen is None or shown is None:
        return shown if unseen is None else unseen
    n = dom.alpha - len(dom)
    opts = [(shown, 0.0, abs(shown - current)),
            (unseen, math.log2(n) if n > 1 else 0.0, abs(unseen - current))]
    pick, by, front = FR.frontier_pick(opts, None, {shown: dom.counts.get(shown, 0), unseen: 0},
                                       dom.key, getattr(dom, "seed", None))
    if dom.note is not None:
        dom.note(opts, pick, by, front)
    return pick


def _walk_unseen(evaluate, current: int, ordered: bool, dom: _PricedDomain, limit, dk):
    """_priced_hit's unseen walk: the nearest satisfying unseen value, ring by ring, tied by the
    draw (comparable-only: every unseen value). OFF's path and the interval bound's check."""
    WALK_N["calls"] += 1

    def ev(v):
        WALK_N["evals"] += 1
        return evaluate(v)
    purse = getattr(dom, "purse", None)     # C2 P1: the purse, checked between rings
    if ordered:
        for d in range(1, limit):
            cap.head()
            if purse is not None and purse(d):
                return PURSE_CUT
            ring = [v for v in (current - d, current + d)
                    if 0 <= v < dom.alpha and v not in dom and ev(v)]
            if ring:
                return min(ring, key=dk)
        return None
    if purse is not None:       # comparable-only: draw order, the first that satisfies, as min(dk)
        for i, v in enumerate(sorted(range(dom.alpha), key=dk)):
            cap.head()
            if purse(i):
                return PURSE_CUT
            if v != current and v not in dom and ev(v):
                return v
        return None
    ring = [v for v in range(dom.alpha) if v != current and v not in dom and ev(v)]
    return min(ring, key=dk) if ring else None


def _value_breaks(term: Term, ctx: Ctx) -> set | None:
    """THE INTERVAL BOUND'S BREAKPOINTS (the reviewer 2026-10-21 17:46) for `term` on an int: {0}
    (a failed guard returns the value, read as bool(v)) and those of the first atom that reads
    the value -- an identity, or a pass_or_zero with no operand, hands it on; every later atom reads
    that atom's output and ctx alone, so it keeps the pieces. None (the walk) if any atom has no
    declared row or a breakpoint is not an int."""
    out = {0}
    first = True
    for a in term.atoms:
        k = G_VALUE_TURNS.get(a.fn)
        if k is None or k == "walk":
            return None
        if not first or k == "identity" or (k == "pass_or_zero" and not ctx.operands):
            continue
        first = False
        if k == "operand":
            vals = tuple(ctx.operands[:1])
        elif k == "group":
            vals = tuple(getattr(ctx, "group", ()) or ())
        else:
            vals = (1,) if k == "zero_one" else ()
        for x in vals:
            cap.head()
            if not isinstance(x, int):
                return None
            out.add(int(x))
    return out


def _bound_unseen(evaluate, current: int, ordered: bool, dom: _PricedDomain, cuts: set, limit, dk):
    """_walk_unseen's answer from the pieces: the in-range breakpoints as singletons and the runs
    between them, each read once. Ordered: the nearest satisfying unseen value's distance, then THAT
    ring evaluated as the walk evaluates it and tied by the same draw; comparable-only: every value
    of a satisfying piece, the same draw."""
    alpha = dom.alpha
    spans, lo = [], 0
    for b in sorted(b for b in cuts if 0 <= b < alpha):
        cap.head()
        if lo < b:
            spans.append((lo, b - 1))
        spans.append((b, b))
        lo = b + 1
    if lo < alpha:
        spans.append((lo, alpha - 1))
    true = [(a, z) for a, z in spans if evaluate(a)]
    if not ordered:
        ring = [v for a, z in true for v in range(a, z + 1) if v != current and v not in dom]
        return min(ring, key=dk) if ring else None
    near = None
    for a, z in true:
        cap.head()
        for v, step, end in ((min(z, current - 1), -1, a), (max(a, current + 1), 1, z)):
            while (v >= end if step < 0 else v <= end) and v in dom:
                cap.head()
                v += step
            if (v >= end if step < 0 else v <= end):
                d = abs(v - current)
                near = d if near is None else min(near, d)
    if near is None or near >= limit:
        return None
    ring = [v for v in (current - near, current + near)
            if 0 <= v < alpha and v not in dom and evaluate(v)]
    return min(ring, key=dk) if ring else None


def _recording(chains, into: list):
    """Yield each chain, recording it into `into`: pass 2 walks that record, a LOOKUP of what pass 1
    reached and never a second enumeration (the reviewer 19:45Z; Fig 12: nothing is re-earned)."""
    for c in chains:
        cap.head()
        into.append(c)
        yield c


# COLD START (ii), SHAPE A (the reviewer 2026-10-21 23:27): a clone whose library/ is partial or
# absent fails at wire(), naming each missing file, before any step; before, a missing file raised
# deep in the first lookup and an absent library/ ran with no vocabulary, silently. OFF only for the
# ablation clause (run without the inheritance): an absent library/ then runs as before, and the
# @run header says "absent (ablation)". A partial library/ is a broken clone either way.
_LIBRARY_REQUIRED = armflag.arm("TETHER_LIBRARY_REQUIRED", default=True)
# the two layers Library.load reads only if present (library_runtime 311-314); neither ships today
LIBRARY_OPTIONAL = ("library/runtime.json", "library/learnings.json")
LIBRARY_HOME = os.path.dirname(os.path.abspath(__file__))


def library_state() -> str:
    """"present", "absent" ("absent (ablation)" with the arm OFF) or "partial: <missing files>",
    read from disk against the loaders' own list (instruments.Attribution.LIBRARY_FILES, pinned by
    test_gate) less the optional two."""
    if not os.path.isdir(os.path.join(LIBRARY_HOME, "library")):
        return "absent" if _LIBRARY_REQUIRED else "absent (ablation)"
    gone = [p for p in I.Attribution.LIBRARY_FILES if p not in LIBRARY_OPTIONAL
            and not os.path.isfile(os.path.join(LIBRARY_HOME, *p.split("/")))]
    return f"partial: {', '.join(gone)}" if gone else "present"


def library_check() -> str:
    """wire()'s startup check: raises naming what is missing, else the state the header records."""
    s = library_state()
    if s.startswith("partial"):
        raise FileNotFoundError(f"{LIBRARY_HOME}: the library is {s}. The clone is incomplete: "
                                "restore library/ from the repository")
    if s == "absent":
        raise FileNotFoundError(f"{os.path.join(LIBRARY_HOME, 'library')} is absent: the agent's "
                                "inheritance ships with the code; restore library/ from the "
                                "repository (TETHER_LIBRARY_REQUIRED=0 only for the ablation)")
    return s


@cache
def _library():
    """The library runtime, loaded once per process (M4). None if the library is absent."""
    root = os.path.join(LIBRARY_HOME, "library")
    if not os.path.isdir(root):
        return None
    if root not in sys.path:
        sys.path.insert(0, root)
    import library_runtime
    lib = library_runtime.Library(root).load()
    if _ATTR_BRIDGE:
        _attr_bridge(lib)
    return lib


# BUILD 3 ITEM 9, THE A4.6 ATTRIBUTE BRIDGE (the reviewer 2026-11-04 r1151; r793): a PERCEPT atom
# gains the readings its index clusters name -- ATTRIBUTE_INDEX.by_cluster (Isaiah's, hash-checked
# by inherited.by_cluster) through K1's reading -> cluster table inverted -- at the tags' weak
# weight 0.5, never over a reading it holds. Derived only: no corpus text, no new entry, nothing
# imported. The signature carries the arm (compile_term), so no compile made without it is served
# with it.
_ATTR_BRIDGE = armflag.arm("TETHER_ATTR_BRIDGE", default=True)
# ITEM 9b (r1157): the bridge also reads FORCE / SIGNAL through inherited.READING_CLUSTER_DERIVED,
# and the unclustered atoms through the build's grouping (index by_cluster_derived), served only
# against the corpus file it was derived from.
_ATTR_GROUP = armflag.arm("TETHER_ATTR_GROUP", default=True)


def _attr_bridge(lib) -> None:
    bc, why = inherited.by_cluster()
    n: collections.Counter = collections.Counter()
    if not bc:
        lib.attr_bridge = {"skipped": why}
        return
    inv: dict = collections.defaultdict(set)
    for r, cs in inherited.READING_CLUSTER.items():
        for c in cs:
            inv[c].add(r)
    if _ATTR_GROUP:
        for r, (c, _why) in inherited.READING_CLUSTER_DERIVED.items():
            inv[c].add(r)
        d = getattr(lib, "cluster_derived", None) or {}
        if d.get("sha256") != inherited.INDEX_SHA:
            n["grouping skipped: " + (d.get("skipped") or "not derived from this corpus file")] += 1
        else:
            bc = {c: list(ks) for c, ks in bc.items()}
            for k, (c, _why) in d["assigned"].items():
                bc.setdefault(c, []).append(k)
            bc.update(d["new"])
            n["grouped atoms"] = len(d["assigned"]) + sum(map(len, d["new"].values()))
            n["unshared"], n["no attribute"] = len(d["unshared"]), len(d["bare"])
            n["candidate (not read)"] = len(d.get("candidate") or {})
    gained = set()
    for c, keys in sorted(bc.items()):
        reads = sorted(r for r in inv.get(c, ()) if r in lib.readings)
        if not reads:
            n[f"cluster with no reading: {c}"] += len(keys)
            continue
        for k in keys:
            e = lib.get(k)
            if not e or e.get("kind") != "PERCEPT":
                continue
            w = e.setdefault("reads_weight", dict.fromkeys(e.get("reads") or [], 1.0))
            for r in reads:
                if r not in w:
                    w[r] = 0.5
                    e.setdefault("reads", []).append(r)
                    lib.by_reading[r].append((k, 0.5))
                    n["readings added"] += 1
                    gained.add(k)
    n["atoms gaining"] = len(gained)
    lib.attr_bridge = dict(n)


def _ph_sub(s: Any, o: str, x: str) -> Any:
    return s if s is None else s.replace(PH_O, o).replace(PH_X, x)


def _bound(c: Any, sub: Any, atoms: dict, terms: dict | None = None, tk: tuple = ()) -> Any:
    """A held compile under this question's names: the names put back, the bbox pair re-sorted
    (compile_term 296), the Term rebuilt from THIS Gamma's atoms by name. No compile. With `terms`
    (BIND ONCE) the rebuilt Term is looked up by (*tk, held Term), tk naming the atoms and o, x."""
    if c is None:
        return None
    if isinstance(c, compile_term.Refusal):
        return compile_term.Refusal(sub(c.reason))

    def term(t: Term) -> Term:
        return _replace(t, atoms=tuple(atoms[a.name] for a in t.atoms), operand=sub(t.operand),
                        guard_ref=sub(t.guard_ref),
                        operand_term=term(t.operand_term) if t.operand_term is not None else None)
    parties = tuple(sub(p) for p in c.parties)
    slot = sub(c.slot)
    if slot.endswith(".bbox"):
        a, b = sorted(parties)
        slot = f"{a}~{b}.bbox"
    if terms is None:
        t = term(c.term)
    else:
        k = (*tk, c.term)
        t = terms.get(k)
        if t is None:
            t = terms[k] = term(c.term)
            _INDEX_N["bind_once_built"] += 1
        else:
            _INDEX_N["bind_once_shared"] += 1
    return compile_term.Compiled(slot, t, sub(c.operand), parties, c.absent, c.via)


@lru_cache(maxsize=4096)
def _name_rx(names: tuple) -> re.Pattern:
    """(A) by pattern: the owner names as whole names only (o1 never inside o12)."""
    alt = "|".join(re.escape(n) for n in sorted(names, key=len, reverse=True))
    return re.compile(rf"(?<![A-Za-z0-9_])(?:{alt})(?![A-Za-z0-9_])")


def _object_kind(types: Any, code: Any) -> tuple:
    """7l: an object's KIND from what was observed of it -- the sorted attribute types of its
    slots, and its canonical shape code where one is given (3c-CANON). The one kind function:
    Agent._kind and the present categorizer both read it (r1716)."""
    got = tuple(sorted(set(types)))
    return (*got, f"form={code}") if code is not None else got


def _unformed(kind: Any) -> Any:
    """Piece 2 (r1717): a kind without its shape form (3c-CANON's "form=" part) -- the concept a
    one-off shape folds into. Anything that is not a tuple of parts is returned as it is."""
    if not isinstance(kind, tuple):
        return kind
    return tuple(x for x in kind if not (isinstance(x, str) and x.startswith("form=")))


def _delta_kind_of(a: Any, typ: Any, before: Any, after: Any) -> tuple | None:
    """K1: HOW a reading changed -- (cluster, sign, size class), from its attribute, its type and
    one transition. A change reading's kind is its own value's; a level's is its difference's.
    Ordered values: "+" / "-" / "0" and the bit length of the magnitude; unordered ones: "ne" /
    "0" and "-". None with no cluster or no value. The one delta-kind function (r1716)."""
    cl = inherited.READING_CLUSTER.get(a)
    if not cl:
        return None
    if after is NOT_RESOLVED or after is None or (
            a not in inherited.DELTA_READINGS and (before is NOT_RESOLVED or before is None)):
        return None
    if not (typ in ORDERED_TYPES and isinstance(after, int) and not isinstance(after, bool)):
        moved = bool(after) if a in inherited.DELTA_READINGS else after != before
        return (cl[0], "ne" if moved else "0", "-")
    v = after if a in inherited.DELTA_READINGS else after - before
    return (cl[0], "+" if v > 0 else "-" if v < 0 else "0", abs(v).bit_length())


def _categorizer_version() -> str:
    """r1716: the present categorizer's own version -- its two functions' code and the tables
    they read, so a change to either moves the token and the cached contexts re-sort."""
    h = hashlib.sha256()
    for f in (_object_kind, _delta_kind_of, _fail_context):
        h.update(f.__code__.co_code + repr(f.__code__.co_consts).encode())
    h.update(repr((sorted(inherited.READING_CLUSTER.items()), sorted(inherited.DELTA_READINGS),
                   ORDERED_TYPES, _3C_CANON)).encode())
    return h.hexdigest()[:16]


def _fail_context(contact: list) -> tuple:
    """Piece 1 (r1713, r1714, r1716): the PRESENT categorizer -- a failure's context from its raw
    contact alone, computed now by the agent's own kind and delta-kind functions. Reads no name."""
    a, typ, before, after, obs, code = contact
    return (_object_kind((t for _a, t in obs), code if _3C_CANON else None),
            _delta_kind_of(a, typ, before, after))


def _slot_of(c: Any, sub: Any) -> str:
    """A held compile's slot under this question's names: _bound's own slot step (sub, then the bbox
    pair re-sorted), without rebuilding the Term (S1)."""
    slot = sub(c.slot)
    if slot.endswith(".bbox"):
        a, b = sorted(sub(p) for p in c.parties)
        slot = f"{a}~{b}.bbox"
    return slot


def _lands(role: str, a: Any, b: Any, slot: str, sub: Any) -> bool:
    """S1: is this held row needed for a question about `slot`? Every row _index_reach counts
    (a quantified view, a refusal on either side) is kept; otherwise the row's own slot (a CAUSE's
    then-slot) must be the asked one."""
    if role == "CAUSE":
        if (a is None or b is None or isinstance(a, compile_term.Refusal)
                or isinstance(b, compile_term.Refusal)):
            return True
        return _slot_of(b, sub) == slot
    if a is None or isinstance(a, compile_term.Refusal):
        return True
    return _slot_of(a, sub) == slot


def _same(s: Any) -> Any:
    """S1: the names of an already-bound row are this question's; nothing to put back."""
    return s


def _slot_map(role: str, whole: tuple) -> tuple:
    """S1c: a held WHOLE indexed once: landing slot -> its row indices (a CAUSE lands on its
    then-slot), and the rows _index_reach counts for every slot (quantified, a Refusal, a CAUSE
    with None on either side), each list in held order. A bound row's slot is already in the
    question's names, so c.slot is read, never substituted: the same rows _lands keeps."""
    by: dict = {}
    every = []
    for i, (_c, a, b) in enumerate(whole):
        cap.head()
        if (a is None or isinstance(a, compile_term.Refusal)
                or (role == "CAUSE" and (b is None or isinstance(b, compile_term.Refusal)))):
            every.append(i)
        else:
            by.setdefault((b if role == "CAUSE" else a).slot, []).append(i)
    return {k: tuple(v) for k, v in by.items()}, tuple(every)


_LANDING: dict = _cache()  # C4: (sig, entry, role) -> (held list, landing groups, every-slot rows)


def _landing_rows(role: str, held: list, key: tuple, slot: str, sub: Any, tallied: bool) -> tuple:
    """C4 (E1; the reviewer 2026-10-17 08:04): the held indices _lands keeps for `slot`, read from
    the entry's rows grouped ONCE under the placeholders by the slot template they land on, so a
    (pair, slot) question substitutes a few templates instead of every row. The rows _index_reach
    counts for every slot come too: with the tally only the uncounted ones (a CAUSE side None
    with no Refusal), as the scan's `_tally_key is None` test keeps. Held order, as the scan."""
    got = _LANDING.get(key)
    if got is None or got[0] is not held:
        groups: dict = {}
        counted, uncounted = [], []
        for i, (_c, a, b) in enumerate(held):
            cap.head()
            if role == "CAUSE":
                if isinstance(a, compile_term.Refusal) or isinstance(b, compile_term.Refusal):
                    counted.append(i)
                    continue
                if a is None or b is None:
                    uncounted.append(i)
                    continue
                c = b
            else:
                if a is None or isinstance(a, compile_term.Refusal):
                    counted.append(i)
                    continue
                c = a
            bbox = c.slot.endswith(".bbox")
            groups.setdefault((c.slot, tuple(c.parties) if bbox else None), []).append(i)
        got = _LANDING[key] = (held, {g: tuple(v) for g, v in groups.items()},
                               tuple(counted), tuple(uncounted))
    _held, groups, counted, uncounted = got
    out = [i for (tpl, parties), ix in groups.items()
           if (f"{min(sub(p) for p in parties)}~{max(sub(p) for p in parties)}.bbox"
               if parties is not None else sub(tpl)) == slot for i in ix]
    out += uncounted if tallied else (*counted, *uncounted)
    return tuple(sorted(out))


def _core_kind(offers: Any, term: Any) -> str | None:
    """7i: "inherit" when an offer is the library's description of the WHOLE term with its operand
    and the term is one atom or concept, "learn" when it is a whole multi-atom recipe, None when
    no offer equals it (an extension, another operand: new, earned in play)."""
    names = tuple(a.name for a in term.atoms)
    if any(o_["operand"] == term.operand and tuple(a.name for a in o_["term"].atoms) == names
           for o_ in offers):
        return "inherit" if len(names) == 1 else "learn"
    return None


def _tally_key(role: str, a: Any, b: Any, sub: Any) -> str | None:
    """SPEED-2: the key _index_reach counts a row under, or None for a row it reads. The
    reason is the bound text: _bound's Refusal is Refusal(sub(c.reason))."""
    if role == "CAUSE":
        if isinstance(a, compile_term.Refusal):
            return "if: " + sub(a.reason)
        if isinstance(b, compile_term.Refusal):
            return "then: " + sub(b.reason)
        return None
    if a is None:
        return compile_term.QUANTIFIED
    return sub(a.reason) if isinstance(a, compile_term.Refusal) else None


def _pair_tally_of(ag: Any, mkey: tuple) -> tuple | None:
    return (_PAIR_TALLY if ag._atoms_token else ag._pair_tally).get(mkey)


def _whole_rows(role: str, whole: tuple, slot: str, maps: dict, mkey: tuple) -> tuple:
    """S1c: the held indices of a held whole's rows for `slot`, from its slot map (built once)."""
    smap = maps.get(mkey)
    if smap is None:
        smap = maps[mkey] = _slot_map(role, whole)
    return tuple(heapq.merge(smap[0].get(slot, ()), smap[1]))


def _restore(held: list, o: str, x: str) -> list:
    """7e: a held view under the names o and x. Only the name-bearing fields (library view and
    candidates: "condition"; CAUSE "if"/"then") are substituted; every other field is copied."""
    out = []
    for c in held:
        cap.head()
        c = dict(c)
        for f in ("condition", "if", "then"):
            if f in c:
                c[f] = c[f].replace("{o}", o).replace("{x}", x)
        out.append(c)
    return out


def _replace_lib(lib: Any) -> Any:
    """M6: a Library sharing the read-only seed and readings, with its own runtime and indexes."""
    import copy
    p = copy.copy(lib)
    p.runtime = dict(lib.runtime)
    dd = collections.defaultdict
    p.by_reading = dd(list, {k: list(v) for k, v in lib.by_reading.items()})
    p.by_affects = dd(list, {k: list(v) for k, v in lib.by_affects.items()})
    p.ingredient_of = dd(list, {k: list(v) for k, v in lib.ingredient_of.items()})
    return p
